begin;
create extension if not exists pgcrypto;
create extension if not exists citext;
create type public.study_status as enum ('ACTIVE','PAUSED','COMPLETED','ABANDONED');
create type public.study_source as enum ('TIMER','MANUAL');
create type public.member_role as enum ('owner','admin','member');
create type public.visibility as enum ('public','friends','private');

create or replace function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now();return new;end$$;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null check(char_length(display_name) between 1 and 80),username citext unique,avatar_url text,exam_category text,timezone text not null default 'UTC',study_day_reset_minute int not null default 240 check(study_day_reset_minute between 0 and 1439),daily_target_minutes int not null default 0 check(daily_target_minutes between 0 and 1440),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_preferences(owner_id uuid primary key references public.profiles(id) on delete cascade,theme text not null default 'system' check(theme in('light','dark','system')),week_start int not null default 1 check(week_start between 0 and 6),default_timer_mode text not null default 'STOPWATCH',pomodoro_work_minutes int not null default 25,pomodoro_break_minutes int not null default 5,profile_visibility public.visibility not null default 'private',study_time_visibility public.visibility not null default 'friends',current_subject_visibility public.visibility not null default 'friends',leaderboard_enabled boolean not null default true,updated_at timestamptz not null default now());
create table public.subjects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,name text not null check(char_length(name) between 1 and 80),color text not null default '#7568f8',icon text,target_minutes int not null default 0,priority smallint not null default 3 check(priority between 1 and 5),difficulty smallint check(difficulty between 1 and 5),status text not null default 'Not Started',position int not null default 0,archived_at timestamptz,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,name));
create table public.units(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,subject_id uuid not null references public.subjects(id) on delete restrict,name text not null,position int not null default 0,archived_at timestamptz,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.chapters(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,unit_id uuid references public.units(id) on delete restrict,subject_id uuid not null references public.subjects(id) on delete restrict,name text not null,status text not null default 'Not Started',target_minutes int not null default 0,priority smallint not null default 3,difficulty smallint,position int not null default 0,archived_at timestamptz,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.topics(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,chapter_id uuid not null references public.chapters(id) on delete restrict,name text not null,status text not null default 'Not Started',position int not null default 0,archived_at timestamptz,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.tasks(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,subject_id uuid references public.subjects(id) on delete set null,chapter_id uuid references public.chapters(id) on delete set null,title text not null check(char_length(title) between 1 and 240),description text,priority text not null default 'Medium',status text not null default 'OPEN',estimated_minutes int check(estimated_minutes between 0 and 10080),due_at timestamptz,scheduled_at timestamptz,tags text[] not null default '{}',recurrence jsonb check(recurrence is null or jsonb_typeof(recurrence)='object'),position int not null default 0,completed_at timestamptz,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.subtasks(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,task_id uuid not null references public.tasks(id) on delete cascade,title text not null,completed boolean not null default false,position int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.study_sessions(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,subject_id uuid references public.subjects(id) on delete set null,chapter_id uuid references public.chapters(id) on delete set null,topic_id uuid references public.topics(id) on delete set null,task_id uuid references public.tasks(id) on delete set null,status public.study_status not null default 'ACTIVE',source public.study_source not null default 'TIMER',session_type text not null default 'Other',started_at timestamptz not null,paused_at timestamptz,finished_at timestamptz,accumulated_paused_seconds int not null default 0 check(accumulated_paused_seconds>=0),duration_seconds int check(duration_seconds>=0),focus_rating smallint check(focus_rating between 1 and 5),focus_score smallint check(focus_score between 0 and 100),questions_attempted int check(questions_attempted>=0),questions_correct int check(questions_correct>=0),notes text,device_id text,client_request_id uuid not null default gen_random_uuid(),deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,client_request_id));
create unique index one_active_session_per_user on public.study_sessions(owner_id) where status in('ACTIVE','PAUSED') and deleted_at is null;
create table public.daily_goals(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,study_day date not null,target_minutes int not null check(target_minutes>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,study_day));
create table public.exams(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,name text not null,starts_at timestamptz not null,category text,target text,notes text,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.revision_items(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,topic_id uuid not null references public.topics(id) on delete restrict,due_at timestamptz not null,intervals_days int[] not null default '{1,3,7,14,30}',interval_index int not null default 0,status text not null default 'DUE',deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.revision_history(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,revision_item_id uuid not null references public.revision_items(id) on delete cascade,revised_at timestamptz not null default now(),outcome text,notes text);
create table public.planner_events(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,type text not null,title text not null,subject_id uuid references public.subjects(id) on delete set null,task_id uuid references public.tasks(id) on delete set null,starts_at timestamptz not null,ends_at timestamptz not null check(ends_at>starts_at),recurrence jsonb,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.mock_tests(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,exam_id uuid references public.exams(id) on delete set null,name text not null,taken_at timestamptz not null,score numeric not null,max_score numeric not null check(max_score>0),rank int,percentile numeric check(percentile between 0 and 100),duration_minutes int,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.mock_test_sections(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,mock_test_id uuid not null references public.mock_tests(id) on delete cascade,subject_id uuid references public.subjects(id) on delete set null,name text not null,score numeric,max_score numeric,attempted int not null default 0,correct int not null default 0,incorrect int not null default 0,skipped int not null default 0);
create table public.mock_test_mistakes(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,mock_test_id uuid not null references public.mock_tests(id) on delete cascade,chapter_id uuid references public.chapters(id) on delete set null,type text not null check(type in('Concept Gap','Formula Recall','Calculation','Misread','Time Management','Guess','Careless Error','Other')),notes text,created_at timestamptz not null default now());
create table public.groups(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,name text not null,description text,join_code text not null unique default encode(gen_random_bytes(6),'hex'),privacy text not null default 'private',manual_time_counts boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.group_members(group_id uuid not null references public.groups(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,role public.member_role not null default 'member',joined_at timestamptz not null default now(),primary key(group_id,user_id));
create table public.group_invites(id uuid primary key default gen_random_uuid(),group_id uuid not null references public.groups(id) on delete cascade,inviter_id uuid not null references public.profiles(id) on delete cascade,invitee_id uuid references public.profiles(id) on delete cascade,token uuid not null unique default gen_random_uuid(),expires_at timestamptz not null,accepted_at timestamptz,created_at timestamptz not null default now());
create table public.challenges(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,group_id uuid references public.groups(id) on delete cascade,title text not null,metric text not null,target numeric not null,starts_at timestamptz not null,ends_at timestamptz not null,created_at timestamptz not null default now());
create table public.challenge_participants(challenge_id uuid not null references public.challenges(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,joined_at timestamptz not null default now(),primary key(challenge_id,user_id));
create table public.friendships(requester_id uuid not null references public.profiles(id) on delete cascade,addressee_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'pending',created_at timestamptz not null default now(),primary key(requester_id,addressee_id),check(requester_id<>addressee_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,type text not null,title text not null,body text,data jsonb not null default '{}',read_at timestamptz,created_at timestamptz not null default now());

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,display_name,timezone) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),'Student'),'UTC');insert into public.user_preferences(owner_id) values(new.id);return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.is_group_member(g uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.group_members where group_id=g and user_id=auth.uid())$$;
create or replace function public.is_group_admin(g uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.group_members where group_id=g and user_id=auth.uid() and role in('owner','admin'))$$;

alter table public.profiles enable row level security;create policy profile_self on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());
do $$declare t text;begin foreach t in array array['user_preferences','subjects','units','chapters','topics','tasks','subtasks','study_sessions','daily_goals','exams','revision_items','revision_history','planner_events','mock_tests','mock_test_sections','mock_test_mistakes','notifications'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy owner_isolation on public.%I for all using (owner_id=auth.uid()) with check (owner_id=auth.uid())',t);end loop;end$$;
alter table public.groups enable row level security;create policy group_read_member on public.groups for select using(owner_id=auth.uid() or public.is_group_member(id));create policy group_create on public.groups for insert with check(owner_id=auth.uid());create policy group_manage on public.groups for update using(public.is_group_admin(id)) with check(public.is_group_admin(id));
alter table public.group_members enable row level security;create policy member_read on public.group_members for select using(public.is_group_member(group_id));create policy member_join_self on public.group_members for insert with check(user_id=auth.uid());create policy member_admin_update on public.group_members for update using(public.is_group_admin(group_id));create policy member_leave on public.group_members for delete using(user_id=auth.uid() or public.is_group_admin(group_id));
alter table public.group_invites enable row level security;create policy invite_read on public.group_invites for select using(invitee_id=auth.uid() or public.is_group_admin(group_id));create policy invite_manage on public.group_invites for all using(public.is_group_admin(group_id)) with check(public.is_group_admin(group_id));
alter table public.challenges enable row level security;create policy challenge_member_read on public.challenges for select using(owner_id=auth.uid() or public.is_group_member(group_id));create policy challenge_owner_write on public.challenges for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
alter table public.challenge_participants enable row level security;create policy participant_read on public.challenge_participants for select using(user_id=auth.uid() or exists(select 1 from public.challenges c where c.id=challenge_id and public.is_group_member(c.group_id)));create policy participant_self on public.challenge_participants for all using(user_id=auth.uid()) with check(user_id=auth.uid());
alter table public.friendships enable row level security;create policy friendship_party on public.friendships for all using(requester_id=auth.uid() or addressee_id=auth.uid()) with check(requester_id=auth.uid() or addressee_id=auth.uid());
create index sessions_owner_started on public.study_sessions(owner_id,started_at desc) where deleted_at is null;create index tasks_owner_due on public.tasks(owner_id,due_at) where deleted_at is null;create index revision_owner_due on public.revision_items(owner_id,due_at) where deleted_at is null;create index planner_owner_start on public.planner_events(owner_id,starts_at) where deleted_at is null;create index mocks_owner_taken on public.mock_tests(owner_id,taken_at desc) where deleted_at is null;
commit;
